4|// they never touch music state.
5|"use client";
6|
7|import { Fragment, useEffect, useMemo, useRef, useState } from "react";
8|import { useRouter } from "next/navigation";
9|import { buildNavIndex, navReducer, subPageCount, subPageKind, textPageAt } from "@/core/reader";
10|import type { NavAction, SceneView } from "@/core/reader";
11|import { effectiveImageStylePref, loadImageStylePref, saveImageStylePref } from "../image-style";
12|import type { ImageStylePref } from "../image-style";
13|import { DEFAULT_SKIN } from "../skin";
14|import { BandPager, Divider } from "../folio/chrome";
15|import { figuresAfter, groupFiguresByEndN, pageOfOrdinal } from "../folio/figure-placement";
16|import { ImagePane } from "../folio/image-pane";
17|import { InlineFigureView, SelectionPopover } from "../folio/inline-figures";
18|import { Lightbox } from "../folio/lightbox";
19|import { edges, readOnLabel, wheelTurn } from "../folio/scroll-turn";
20|import type { WheelTurnState } from "../folio/scroll-turn";
21|import { usePictures } from "../folio/use-pictures";
22|import type { InlineFigure } from "../folio/use-pictures";
23|import { PictureVault } from "../folio/vault";
24|import {
25|  chapterSetAside,
26|  coverTitleLong,
27|  markChapterEndReached,
28|  markChapterSetAside,
29|  markPanelsShownAnyway,
30|  panelsUnlocked,
31|} from "../folio/panels";
32|import type { ChapterPanel } from "../folio/panels";
33|import {
34|  BlurredThumbs,
