41|// One-shot entry intent: set just before pushing the previous scene
42|// route, so the new page opens on its last sub-page. Client memory only,
43|// never the URL, so prerendered pages stay static and a direct URL load
44|// always starts at page 0.
45|let enterAtEnd = false;
46|
47|// Survives scene remounts so one swipe never turns twice.
48|let wheelState: WheelTurnState = { acc: 0, lockedUntil: 0, lastAt: 0 };
49|
50|// Set on every in-app scene push. The heading takes focus only when this
51|// is set, so first load shows no focus ring.
52|let hasNavigated = false;
53|
54|// True when the wheel target sits inside a nested scroller (picture
55|// vault, player bar, modal grids): those scroll natively and never turn
56|// pages. The reading column itself is not a nested scroller.
57|function inNestedScroller(target: HTMLElement | null, readCol: HTMLElement | null): boolean {
58|  let el: HTMLElement | null = target;
59|  while (el !== null) {
60|    if (el !== readCol) {
61|      const overflowY = window.getComputedStyle(el).overflowY;
62|      if ((overflowY === "auto" || overflowY === "scroll") && el.scrollHeight > el.clientHeight) {
63|        return true;
64|      }
65|    }
66|    el = el.parentElement;
67|  }
68|  return false;
69|}
