71|function pulse(el: HTMLElement | null) {
72|  if (!el) return;
73|  el.classList.remove("pulse");
74|  void el.offsetWidth;
75|  el.classList.add("pulse");
76|  window.setTimeout(() => el.classList.remove("pulse"), 650);
