79|// One scene view: sub-pages, keys, buttons, progress, chapter jump.
80|// Sub-page moves stay in client state; scene moves push a new route.
81|export function ScenePage({
82|  view,
83|  views,
84|  bookId,
85|  textVersion,
86|  bookIndex,
87|  bookTotal,
88|  panels,
89|  nextChapter,
90|}: {
91|  view: SceneView;
92|  views: { sceneId: string; pages: number }[];
93|  bookId: string;
94|  textVersion: string;
95|  bookIndex: number;
96|  bookTotal: number;
97|  panels: ChapterPanel[];
98|  nextChapter: { ch: number; firstSceneId: string } | null;
99|}) {
100|  const [storedPref, setStoredPref] = useState<ImageStylePref | null>(null);
101|  const pref = effectiveImageStylePref(storedPref, DEFAULT_SKIN);
102|  const pic = usePictures({ bookId, textVersion, sceneId: view.sceneId, pref });
103|  const router = useRouter();
104|  const index = useMemo(() => buildNavIndex(views), [views]);
105|  const cover = view.isChapterFirst;
106|  const end = view.isChapterLast;
107|  const coverLong = coverTitleLong(view.chapterTitle);
108|  const total = subPageCount(view.pages.length, cover, end);
109|  const lastPage = total - 1;
110|  const [page, setPage] = useState(() => {
111|    if (enterAtEnd) {
112|      enterAtEnd = false;
113|      return lastPage;
114|    }
115|    return 0;
116|  });
117|  const [panelsOpen, setPanelsOpen] = useState(false);
118|  const [gateOpen, setGateOpen] = useState(false);
119|  const [offerAside, setOfferAside] = useState(() => chapterSetAside(view.ch));
120|  const gateOpener = useRef<HTMLElement | null>(null);
121|  const headingRef = useRef<HTMLHeadingElement>(null);
122|  const readColRef = useRef<HTMLDivElement | null>(null);
123|  const figEls = useRef(new Map<string, HTMLElement>());
124|  const kind = subPageKind(page, view.pages.length, cover, end);
125|  const sub = kind === "text" ? (view.pages[textPageAt(page, cover)] ?? view.pages[0]) : undefined;
126|  const textIndex = textPageAt(page, cover);
127|  const atStart = view.prevSceneId === null && page === 0;
128|  const atBookEnd = view.nextSceneId === null && page === lastPage;
129|  const readOn =
130|    kind === "text"
131|      ? readOnLabel({
132|          textIndex,
133|          textCount: view.pages.length,
134|          hasEndPage: end,
135|          hasNextSceneInChapter: view.k < view.n,
136|          ch: view.ch,
137|        })
138|      : null;
139|
140|  useEffect(() => {
141|    setStoredPref(loadImageStylePref());
142|  }, []);
143|
144|  // The end page marks the chapter finished, unlocking the panels.
145|  useEffect(() => {
146|    if (kind === "end") markChapterEndReached(view.ch);
147|  }, [kind, view.ch]);
148|
149|  function changePref(next: ImageStylePref) {
150|    setStoredPref(next);
151|    saveImageStylePref(next);
152|  }
153|
154|  function requestPanels(opener: HTMLElement | null) {
155|    if (panelsUnlocked(view.ch)) {
156|      setPanelsOpen(true);
157|      return;
158|    }
159|    gateOpener.current = opener;
160|    setGateOpen(true);
161|  }
162|
163|  function showAnyway() {
164|    markPanelsShownAnyway(view.ch);
165|    setGateOpen(false);
166|    setPanelsOpen(true);
167|  }
168|
169|  function notYet() {
170|    setGateOpen(false);
171|    gateOpener.current?.focus?.();
172|    gateOpener.current = null;
173|  }
174|
175|  function readFirst() {
176|    markChapterSetAside(view.ch);
177|    setOfferAside(true);
178|  }
179|
180|  function goNextChapter() {
181|    if (!nextChapter) return;
182|    hasNavigated = true;
183|    router.push(`/leer/${nextChapter.firstSceneId}`);
184|  }
185|
186|  const figsByN = useMemo(() => groupFiguresByEndN(pic.figures), [pic.figures]);
187|
188|  function gotoFigure(fig: InlineFigure) {
189|    const at = pageOfOrdinal(view.pages, fig.endN);
190|    if (at < 0) return;
191|    setPage(at + (cover ? 1 : 0));
192|    readColRef.current?.scrollTo(0, 0);
193|    requestAnimationFrame(() => {
194|      requestAnimationFrame(() => {
195|        const el = figEls.current.get(fig.id) ?? null;
196|        el?.scrollIntoView({ block: "nearest" });
197|        pulse(el);
198|      });
199|    });
200|  }
201|
202|  function gotoScenePicture() {
203|    const img = document.querySelector(".img-pane .pane-img");
204|    pulse(img instanceof HTMLElement ? img : null);
205|  }
206|
207|  // Every pager move runs through navReducer; a new scene id means a
208|  // route push, a same-scene result means a client sub-page move.
209|  function move(action: NavAction) {
210|    pic.hidePopover();
211|    const next = navReducer({ sceneId: view.sceneId, page }, action, index);
212|    if (next.sceneId !== view.sceneId) {
213|      hasNavigated = true;
214|      if (next.page > 0) enterAtEnd = true;
215|      router.push(`/leer/${next.sceneId}`);
216|      return;
217|    }
218|    if (next.page !== page) {
219|      setPage(next.page);
220|      readColRef.current?.scrollTo(0, 0);
221|    }
222|  }
223|
224|  function goNext() {
225|    move({ kind: "next" });
226|  }
227|
228|  function goPrev() {
229|    move({ kind: "prev" });
230|  }
231|
232|  // Scene entry resets orientation; sub-page moves keep the heading.
233|  useEffect(() => {
234|    if (hasNavigated) headingRef.current?.focus();
235|    readColRef.current?.scrollTo(0, 0);
236|  }, [view.sceneId]);
237|
238|  useEffect(() => {
239|    const onKey = (event: KeyboardEvent) => {
240|      if (event.metaKey || event.ctrlKey || event.altKey) return;
241|      const target = event.target as HTMLElement | null;
242|      if (
243|        target &&
244|        (target.tagName === "INPUT" ||
245|          target.tagName === "SELECT" ||
246|          target.tagName === "TEXTAREA" ||
247|          target.isContentEditable)
248|      ) {
249|        return;
250|      }
251|      if (event.key === "ArrowRight") {
252|        event.preventDefault();
253|        goNext();
254|      } else if (event.key === "ArrowLeft") {
255|        event.preventDefault();
256|        goPrev();
257|      } else if (
258|        event.key === " " ||
259|        event.key === "PageDown" ||
260|        event.key === "ArrowDown" ||
261|        event.key === "PageUp" ||
262|        event.key === "ArrowUp"
263|      ) {
264|        if (target !== null && target.tagName === "BUTTON") return;
265|        const forward =
266|          event.key === "PageDown" || event.key === "ArrowDown" || (event.key === " " && !event.shiftKey);
267|        event.preventDefault();
268|        const col = readColRef.current;
269|        if (col !== null) {
270|          const at = edges(col);
271|          if ((forward && !at.atBottom) || (!forward && !at.atTop)) {
272|            col.scrollBy({ top: (forward ? 1 : -1) * col.clientHeight * 0.85, behavior: "smooth" });
273|            return;
274|          }
275|        }
276|        if (forward) goNext();
277|        else goPrev();
278|      }
279|    };
280|    window.addEventListener("keydown", onKey);
281|    return () => window.removeEventListener("keydown", onKey);
282|  }, [page, view.sceneId, index, router]);
283|
284|  // Wheel and trackpad turn pages: at a column edge, an accumulated swipe
285|  // calls goNext/goPrev. preventDefault only on a turn, so the column
286|  // keeps scrolling natively until it rests on its edge.
287|  useEffect(() => {
288|    const onWheel = (event: WheelEvent) => {
289|      if (panelsOpen || gateOpen || pic.lightbox.item !== null) return;
290|      if (event.ctrlKey) return;
291|      if (Math.abs(event.deltaX) > Math.abs(event.deltaY)) return;
292|      const target = event.target instanceof HTMLElement ? event.target : null;
293|      const readCol = readColRef.current;
294|      if (inNestedScroller(target, readCol)) return;
295|      const at = readCol === null ? { atTop: true, atBottom: true } : edges(readCol);
296|      const result = wheelTurn(wheelState, {
297|        deltaY: event.deltaY,
298|        deltaMode: event.deltaMode,
299|        now: performance.now(),
300|        atTop: at.atTop,
301|        atBottom: at.atBottom,
302|      });
303|      wheelState = result.state;
304|      if (result.turn === "next") {
305|        event.preventDefault();
306|        goNext();
307|      } else if (result.turn === "prev") {
308|        event.preventDefault();
309|        goPrev();
310|      }
311|    };
312|    window.addEventListener("wheel", onWheel, { passive: false });
313|    return () => window.removeEventListener("wheel", onWheel);
314|  }, [page, view.sceneId, index, router, panelsOpen, gateOpen, pic.lightbox.item]);
315|
316|  return (
317|    <>
318|      <ImagePane
319|        // The cover always shows the placeholder: nothing to picture yet,
320|        // and a cached scene picture would spoil the chapter.
321|        card={kind === "cover" ? { phase: "idle" } : pic.card}
322|        onPicture={() => pic.illustrateScene()}
323|        onRetry={() => pic.illustrateScene()}
324|        onClear={pic.clearScene}
325|        onOpen={pic.lightbox.open}
326|        bare={kind === "cover"}
327|        onPictureChapter={
328|          kind === "cover" ? null : kind === "end" ? () => setPanelsOpen(true) : requestPanels
329|        }
330|      />
331|      <Divider />
332|      <div className="read-col" ref={readColRef} aria-label="Reading column">
333|        {kind === "cover" ? (
334|          <>
335|            <div className="kicker">Chapter</div>
336|            <p className="cover-num" data-long={coverLong} aria-label={`Chapter ${view.ch}`}>
337|              {view.ch}
338|            </p>
339|            <h1
340|              className="chapter-title cover-title"
341|              data-long={coverLong}
342|              id="scene-heading"
343|              ref={headingRef}
344|              tabIndex={-1}
345|            >
346|              {view.chapterTitle}
347|            </h1>
348|            <hr className="cover-rule" />
349|            {offerAside ? (
350|              <PanelsQuietLink onOpen={requestPanels} />
351|            ) : (
352|              <PanelsOfferCard panels={panels} onShowAnyway={showAnyway} onReadFirst={readFirst} />
353|            )}
354|            <button type="button" className="cover-begin" onClick={goNext}>
355|              Begin the chapter →
356|            </button>
357|            <span className="read-on-hint">or just scroll</span>
358|          </>
359|        ) : kind === "end" ? (
360|          <>
361|            <div className="kicker">End of Chapter {view.ch}</div>
362|            <div className="end-card">
363|              <BlurredThumbs panels={panels} unblurredCount={Math.min(4, panels.length)} />
364|              <h2>Relive this chapter in panels</h2>
365|              <div className="panels-btns">
366|                <button type="button" className="panels-primary" onClick={() => setPanelsOpen(true)}>
367|                  Open the panels
368|                </button>
369|              </div>
370|            </div>
371|            {nextChapter ? (
372|              <button type="button" className="end-next" onClick={goNextChapter}>
373|                On to Chapter {nextChapter.ch} →
374|              </button>
375|            ) : (
376|              <p className="the-end">The end.</p>
377|            )}
378|          </>
379|        ) : (
380|          <>
381|            <div className="kicker">Chapter {view.ch}</div>
382|            <h1 className="chapter-title" id="scene-heading" ref={headingRef} tabIndex={-1}>
383|              {view.chapterTitle}
384|            </h1>
385|            <div className="scene-line">
386|              <span>
387|                Scene {view.k} of {view.n}
388|                {view.pages.length > 1 ? ` · Page ${textIndex + 1} of ${view.pages.length}` : ""}
389|              </span>
390|            </div>
391|            <div className={`body-text${textIndex === 0 ? " dropcap" : ""}`} ref={pic.viewRef}>
392|              {sub?.paragraphs.map((p, i, arr) => (
393|                <Fragment key={p.id}>
394|                  <p id={p.id} data-n={p.n} data-cont={p.cont ? true : undefined}>
395|                    {p.text}
396|                  </p>
397|                  {/* A figure for n lands after its last visible fragment. */}
398|                  {figuresAfter(arr, i, figsByN).map((fig) => (
399|                    <InlineFigureView
400|                      key={fig.id}
401|                      figure={fig}
402|                      onRemove={() => pic.removeFigure(fig.id)}
403|                      onRetry={() => pic.retryFigure(fig.id)}
404|                      onOpen={pic.lightbox.open}
405|                      refCb={(el) => {
406|                        if (el) figEls.current.set(fig.id, el);
407|                        else figEls.current.delete(fig.id);
408|                      }}
409|                    />
410|                  ))}
411|                </Fragment>
412|              ))}
413|              {pic.popover !== null ? (
414|                <SelectionPopover
415|                  pos={pic.popover}
416|                  popRef={pic.popRef}
417|                  onPick={() => pic.illustratePassage()}
418|                />
419|              ) : null}
420|              {/* Every read-on label ends with " ↓"; the arrow gets its own span for the hover nudge. */}
421|              {readOn !== null ? (
422|                <button type="button" className="read-on" onClick={goNext}>
423|                  {readOn.slice(0, -1)}
424|                  <span className="read-on-arrow" aria-hidden="true">
425|                    ↓
426|                  </span>
427|                </button>
428|              ) : null}
429|            </div>
430|          </>
431|        )}
432|      </div>
433|      <PictureVault
434|        scene={pic.card.phase === "ready" ? { url: pic.card.url, caption: pic.card.caption } : null}
435|        figures={pic.figures}
436|        onGotoScene={gotoScenePicture}
437|        onGotoFigure={gotoFigure}
438|        onOpen={pic.lightbox.open}
439|        pref={pref}
440|        onPrefChange={changePref}
441|      />
442|      <BandPager
443|        k={view.k}
444|        n={view.n}
445|        bookIndex={bookIndex}
446|        bookTotal={bookTotal}
447|        onPrev={goPrev}
448|        onNext={goNext}
449|        atStart={atStart}
450|        atBookEnd={atBookEnd}
451|      />
452|      <Lightbox item={pic.lightbox.item} onClose={pic.lightbox.close} />
453|      {gateOpen ? <SpoilerGateDialog onShow={showAnyway} onNotYet={notYet} /> : null}
454|      {panelsOpen ? (
455|        <PanelsModal
456|          ch={view.ch}
457|          chapterTitle={view.chapterTitle}
458|          panels={panels}
459|          onClose={() => setPanelsOpen(false)}
460|          onOpenArt={pic.lightbox.open}
461|        />
462|      ) : null}
463|    </>
464|  );
465|}

