1|// Drawing style preference for POST /api/images. Persisted in
2|// localStorage, parsed defensively. Preset ids come from the server's
3|// table so they always match; the server re-checks custom text.
4|import { IMAGE_STYLE_PRESETS, resolveEffectiveStyle } from "@/core/image-style";
5|import type { ImageStylePresetId, StyleChoice } from "@/core/image-style";
6|
7|export const IMAGE_STYLE_KEY = "lectoria.imageStyle";
8|
9|export type ImageStylePref = { kind: "preset"; id: string } | { kind: "custom"; text: string };
10|
11|export interface StylePreset {
12|  id: string;
13|  label: string;
14|}
15|
16|export const STYLE_PRESETS: StylePreset[] = IMAGE_STYLE_PRESETS.map(({ id, label }) => ({ id, label }));
17|
18|export const DEFAULT_IMAGE_STYLE: ImageStylePref = { kind: "preset", id: "denslow" };
19|
20|export const STYLE_OTHER_VALUE = "__other";
21|
22|// The select shows Other… while its custom field is open, even when the
23|// saved pref is still a preset; Escape or a preset choice closes it.
24|export function resolveStyleSelect(pref: ImageStylePref, otherOpen: boolean): string {
25|  return otherOpen || pref.kind === "custom" ? STYLE_OTHER_VALUE : pref.id;
26|}
27|
28|export const DENSLOW_CREDIT = "In the style of W. W. Denslow";
29|
30|function toImageStylePref(json: unknown): ImageStylePref | null {
31|  if (typeof json === "object" && json !== null && !Array.isArray(json)) {
32|    const pref = json as Record<string, unknown>;
33|    if (pref.kind === "preset" && typeof pref.id === "string" && STYLE_PRESETS.some((p) => p.id === pref.id)) {
34|      return { kind: "preset", id: pref.id };
35|    }
36|    if (pref.kind === "custom" && typeof pref.text === "string" && pref.text.trim().length > 0) {
37|      return { kind: "custom", text: pref.text.trim().slice(0, 60) };
38|    }
39|  }
40|  return null;
41|}
42|
43|export function parseImageStylePref(json: unknown): ImageStylePref {
44|  return toImageStylePref(json) ?? DEFAULT_IMAGE_STYLE;
45|}
46|
47|// Null means no explicit pick stored. Invalid stored values also read
48|// as null so the skin default (Denslow today) applies.
49|export function loadImageStylePref(): ImageStylePref | null {
50|  try {
51|    if (typeof window === "undefined") return null;
52|    const raw = window.localStorage.getItem(IMAGE_STYLE_KEY);
53|    if (!raw) return null;
54|    return toImageStylePref(JSON.parse(raw) as unknown);
55|  } catch {
56|    return null;
57|  }
58|}
59|
60|// The picker shows this; the request sends requestStyleFields of it.
61|// No explicit pick falls back to the skin default (Denslow today).
62|export function effectiveImageStylePref(pref: ImageStylePref | null, skin?: string): ImageStylePref {
63|  const explicit: StyleChoice | undefined =
64|    pref === null
65|      ? undefined
66|      : pref.kind === "custom"
67|        ? { custom: pref.text }
68|        : { preset: pref.id as ImageStylePresetId };
69|  const eff = resolveEffectiveStyle(explicit, skin);
70|  return "custom" in eff ? { kind: "custom", text: eff.custom } : { kind: "preset", id: eff.preset };
71|}
72|
73|export function saveImageStylePref(pref: ImageStylePref): void {
74|  try {
75|    if (typeof window === "undefined") return;
76|    window.localStorage.setItem(IMAGE_STYLE_KEY, JSON.stringify(pref));
77|  } catch {
78|    // Private mode: new pictures use the default until reload.
79|  }
80|}
81|
82|// Denslow sends nothing, so its key and prompt stay byte-identical.
83|export function requestStyleFields(pref: ImageStylePref): { style?: StyleChoice } {
84|  if (pref.kind === "custom") return { style: { custom: pref.text } };
85|  if (pref.id === "denslow") return {};
86|  return { style: { preset: pref.id as ImageStylePresetId } };
87|}
88|
89|// The credit never claims a style the request did not send.
90|export function styleCredit(fields: { style?: StyleChoice }): string {
91|  const style = fields.style;
92|  if (style === undefined) return DENSLOW_CREDIT;
93|  if ("preset" in style) {
94|    return STYLE_PRESETS.find((p) => p.id === style.preset)?.label ?? DENSLOW_CREDIT;
95|  }
96|  return style.custom;
97|}

