82|// Denslow sends nothing, so its key and prompt stay byte-identical.
83|export function requestStyleFields(pref: ImageStylePref): { style?: StyleChoice } {
84|  if (pref.kind === "custom") return { style: { custom: pref.text } };
85|  if (pref.id === "denslow") return {};
86|  return { style: { preset: pref.id as ImageStylePresetId } };
