17|    expect(withoutHoverBlock).not.toMatch(/\.skip\.rain:hover/);
18|  });
19|
20|  it("keys state-change animations on data-anim, never on mount", () => {
21|    for (const cls of ["face", "drop", "bolt", "etch", "draw", "bloom", "wet"]) {
22|      expect(css).toMatch(new RegExp(`\\[data-anim\\][\\s\\S]*?\\.${cls}[\\s,{]`));
23|    }
24|    expect(css).not.toMatch(/\.skip\.rain \.face\s*\{[^}]*animation:/);
25|  });
26|
27|  it("keeps the button boxless with the art sized inside the hit area", () => {
